<?php
require __DIR__.'/config.php';require __DIR__.'/database_upgrade.php';try{$pdo=db();apply_database_upgrade($pdo);}catch(Throwable $e){exit('Reports are unavailable.');}
if(!is_role('customer')){flash('Customer access is required.','error');redirect('index.php?page=login');}$u=user();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$bid=(int)$_POST['business_id'];$reason=$_POST['reason']??'';$valid=['fake_business','wrong_information','inappropriate_content','duplicate_listing','closed_business','other'];if(!in_array($reason,$valid,true)){flash('Choose a report reason.','error');redirect('index.php?page=business&id='.$bid);}$q=$pdo->prepare('SELECT id FROM businesses WHERE id=? AND status="approved"');$q->execute([$bid]);if(!$q->fetchColumn()){exit('Business unavailable.');}$pdo->prepare('INSERT INTO business_reports(business_id,user_id,reason,details) VALUES(?,?,?,?)')->execute([$bid,$u['id'],$reason,mb_strimwidth(trim($_POST['details']??''),0,3000,'')]);audit($pdo,$u['id'],'Business reported','Business #'.$bid);flash('Thank you. Your report was submitted for review.');redirect('index.php?page=business&id='.$bid);}
